import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import {Text,View,type ViewProps} from 'react-native';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {useLocalStore} from '@/components/nyc-tron/ui/components/useLocalStore';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {SettingSwitch} from '@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch';
import {MotionVectorFields} from '@/components/nyc-tron/ui/components/forge/motion/MotionVectorFields';
import {validateMotionCamera,validateMotionLight,type MotionCamera,type MotionLight} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export type {MotionCamera,MotionLight} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export interface CameraAndLightControlsProps extends Omit<ViewProps,'children'> {readonly camera:MotionCamera;readonly light:MotionLight;readonly onCameraCommit:(value:MotionCamera)=>void;readonly onLightCommit:(value:MotionLight)=>void;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Lens/view/depth and lighting values, independent from native app window dimensions. */
export function CameraAndLightControls({camera,light,onCameraCommit,onLightCommit,disabled=false,unstyled=false,...props}:CameraAndLightControlsProps){
 validateMotionCamera(camera);validateMotionLight(light);
 const [local,store]=useLocalStore(()=>({error:null as string|null}));
 const setCamera=(change:Partial<MotionCamera>)=>{if(disabled)return;const next={...camera,...change};try{validateMotionCamera(next);}catch(error){store.set({error:error instanceof Error?error.message:'Invalid camera target'});return;}store.set({error:null});onCameraCommit(next);};
 const setLight=(change:Partial<MotionLight>)=>{if(disabled)return;const next={...light,...change};validateMotionLight(next);onLightCommit(next);};
 return <View {...props} style={[{gap:10},props.style]}>
  <ErrorMessage {...(local.error?{message:local.error}:{})} unstyled={unstyled}/>
  <Select label="Camera projection" value={camera.projection} options={[{value:'perspective',label:'Perspective'},{value:'orthographic',label:'Orthographic'}]} disabled={disabled} unstyled={unstyled} onValueChange={projection=>setCamera({projection:projection as MotionCamera['projection']})}/>
  <MotionVectorFields label="Camera position" value={camera.position} disabled={disabled} unstyled={unstyled} onCommit={position=>setCamera({position})}/>
  <MotionVectorFields label="Camera target" value={camera.target} disabled={disabled} unstyled={unstyled} onCommit={target=>setCamera({target})}/>
  {([['focalLengthMm','Camera focal length mm',.1,100000],['sensorWidthMm','Camera sensor width mm',.1,100000],['near','Camera near clip',.000001,camera.far-.000001],['far','Camera far clip',camera.near+.000001,1e12],['orthographicSize','Orthographic view size',.000001,1e9],['focusDistance','Camera focus distance',.000001,1e12],['aperture','Camera aperture',.1,128]] as const).map(([key,label,min,max])=><UnitInput key={key} label={label} value={camera[key]} min={min} max={max} step={.1} precision={6} disabled={disabled||(key==='orthographicSize'?camera.projection!=='orthographic':key==='focalLengthMm'||key==='sensorWidthMm'?camera.projection!=='perspective':key==='focusDistance'||key==='aperture'?!camera.depthOfField:false)} unstyled={unstyled} onCommit={number=>setCamera({[key]:number})}/>)}
  <SettingSwitch label="Camera depth of field" on={camera.depthOfField} onChange={depthOfField=>setCamera({depthOfField})} disabled={disabled} styled={!unstyled}/>
  <Select label="Motion light type" value={light.type} options={['point','spot','directional','ambient'].map(value=>({value,label:value}))} disabled={disabled} unstyled={unstyled} onValueChange={type=>setLight({type:type as MotionLight['type']})}/>
  <MotionVectorFields label="Light position" value={light.position} disabled={disabled||light.type==='ambient'} unstyled={unstyled} onCommit={position=>setLight({position})}/>
  <MotionVectorFields label="Light rotation" value={light.rotation} min={-360000} max={360000} disabled={disabled||light.type==='ambient'||light.type==='point'} unstyled={unstyled} onCommit={rotation=>setLight({rotation})}/>
  <UnitInput label="Light intensity" value={light.intensity} min={0} max={1e6} disabled={disabled} unstyled={unstyled} onCommit={intensity=>setLight({intensity})}/>
  <Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>{`Light working profile: ${light.colorProfileId}`}</Text>
  {(['red','green','blue'] as const).map((channel,index)=><UnitInput key={channel} label={`Linear light ${channel}`} value={light.color[index]!} min={0} max={16} step={.01} disabled={disabled} unstyled={unstyled} onCommit={number=>{const color=[...light.color] as [number,number,number];color[index]=number;setLight({color});}}/>)}
  <UnitInput label="Spot light cone degrees" value={light.coneDegrees} min={.1} max={179.9} disabled={disabled||light.type!=='spot'} unstyled={unstyled} onCommit={coneDegrees=>setLight({coneDegrees})}/>
  <SettingSwitch label="Light casts shadows" on={light.castsShadows} onChange={castsShadows=>setLight({castsShadows})} disabled={disabled||light.type==='ambient'} styled={!unstyled}/>
 </View>;
}

import {View} from 'react-native';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {validateMotionVector,type MotionVector3} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export interface MotionVectorFieldsProps {readonly label:string;readonly value:MotionVector3;readonly onCommit:(value:MotionVector3)=>void;readonly min?:number;readonly max?:number;readonly step?:number;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Common axis entry preserves the two untouched floating coordinates. */
export function MotionVectorFields({label,value,onCommit,min=-1e9,max=1e9,step=1,disabled=false,unstyled=false}:MotionVectorFieldsProps){
 validateMotionVector(value,min,max);return <View style={{gap:6}}>{(['x','y','z'] as const).map(axis=><UnitInput key={axis} label={`${label} ${axis.toUpperCase()}`} value={value[axis]} min={min} max={max} step={step} precision={6} disabled={disabled} unstyled={unstyled} onCommit={number=>{if(disabled||number===value[axis])return;const next={...value,[axis]:number};validateMotionVector(next,min,max);onCommit(next);}}/>)}</View>;
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}
